#define N_TAPS 5
float fir_filter(float input, const float *coeffs, float *buffer) {
    float acc = 0.0f;
    for (int i = N_TAPS - 1; i > 0; i--) buffer[i] = buffer[i - 1];
    buffer[0] = input;
    for (int i = 0; i < N_TAPS; i++) acc += coeffs[i] * buffer[i];
    return acc;
}

